using namespace Star;
static uint64_t cases=0,checks=0;static std::ofstream stream;
static void check(bool b,char const*w){++checks;if(!b){std::cerr<<"COMPARISON "<<w<<" case="<<cases<<"\n";std::exit(1);}}
static void obs(std::string const&s){uint64_t n=s.size();stream.write(reinterpret_cast<char*>(&n),8);stream.write(s.data(),s.size());}
struct Wire:DataStream{std::string bytes;size_t cursor=0;void readData(char*p,size_t n)override{if(n>bytes.size()-cursor)throw std::runtime_error("EOF");std::memcpy(p,bytes.data()+cursor,n);cursor+=n;}void writeData(char const*p,size_t n)override{bytes.append(p,n);}};
using Rows=std::vector<std::string>;
static std::string errorBytes(std::exception const&e){return printException(e,false);}
#ifdef STAR_USE_RUST_ASSET_PATH
static void raw(std::string const&s){size_t N=size_t(-1),first=N,question=N,lastSlash=0;for(size_t i=0;i<s.size();++i){if(first==N&&(s[i]==':'||s[i]=='?'))first=i;if(first==N&&s[i]=='/')lastSlash=i+1;}StarAssetPathSplit want={first,N,0,N};if(first!=N){if(s[first]=='?')want.directive_start=first;else if(first+1<s.size()){size_t begin=first+1;for(size_t i=begin;i<s.size();++i)if(s[i]=='?'){question=i;break;}if(question==N){want.sub_start=begin;want.sub_count=begin+1!=s.size()?N:N-begin;}else{want.directive_start=question;if(question!=begin){want.sub_start=begin;want.sub_count=question-begin;}}}}StarAssetPathSplit m={};StarAssetPathRange r={};auto p=reinterpret_cast<uint8_t const*>(s.data());auto b0=star_asset_path_call_count(0),b1=star_asset_path_call_count(1);check(star_asset_path_split(p,s.size(),&m)==0&&m.base_len==want.base_len&&m.sub_start==want.sub_start&&m.sub_count==want.sub_count&&m.directive_start==want.directive_start,"raw scan exact metadata");check(star_asset_path_filename_range(p,s.size(),&r)==0&&r.start==lastSlash&&r.end==(first==N?s.size():first),"raw scan absolute range");check(star_asset_path_call_count(0)==b0+1&&star_asset_path_call_count(1)==b1+1,"per-case scoped receipts");}
#endif
template<class P>static Rows snapshot(std::string const&s){Rows r;String input(s);auto add=[&](auto fn){try{r.push_back("V"+fn());}catch(std::exception const&e){r.push_back("E"+errorBytes(e));}};
 add([&]{return P::split(input).basePath.utf8();});
 add([&]{auto p=P::split(input);return p.subPath?"present:"+p.subPath->utf8():std::string("absent");});
 add([&]{auto p=P::split(input);std::string v;p.directives.forEach([&](Directives::Entry const&e,Directives const&d){auto x=String(e.string(*d)).utf8();v+=std::to_string(e.operation.typeIndex())+":"+std::to_string(e.begin)+":"+std::to_string(e.length)+":"+std::to_string(x.size())+":"+x;});return v;});
 add([&]{return P::join(P::split(input)).utf8();});add([&]{return P::directory(input).utf8();});add([&]{return P::filename(input).utf8();});add([&]{return P::extension(input).utf8();});
 add([&]{return P::setSubPath(input,"").utf8();});add([&]{return P::setSubPath(input,"s:t").utf8();});add([&]{return P::removeSubPath(input).utf8();});add([&]{return P::getDirectives(input).utf8();});add([&]{return P::removeDirectives(input).utf8();});add([&]{return P::addDirectives(input,"flipx").utf8();});add([&]{return P::relativeTo(input,"next").utf8();});add([&]{return P::relativeTo(input,"/absolute").utf8();});add([&]{return std::to_string(P::isEmbedded(input))+std::to_string(P::isRemote(input));});add([&]{Wire w;w<<P::split(input);P restored;w>>restored;return w.bytes+P::join(restored).utf8()+std::to_string(w.cursor);});add([&]{auto p=P::split(input);std::string v;for(auto const&d:p.directives.list()){v+=String(d.prefix()).utf8();v+='|';v+=d.string().utf8();v+='|';v+=std::to_string(d.size());}return v;});return r;}
static void test(std::string const&s){++cases;auto a=snapshot<AssetPath>(s),b=snapshot<AssetPathReference::AssetPath>(s);check(a==b,"public byte/error/dependency observations");obs(s);for(auto const&x:a)obs(x);
#ifdef STAR_USE_RUST_ASSET_PATH
raw(s);
#endif
}
#ifdef STAR_USE_RUST_ASSET_PATH
static void abi(){const size_t N=size_t(-1);struct C{char const*s;StarAssetPathSplit want;StarAssetPathRange range;};
 for(auto const&c:std::vector<C>{{"",{N,N,0,N},{0,0}},{"a",{N,N,0,N},{0,1}},{"a:",{1,N,0,N},{0,1}},{"a:x",{1,2,N-2,N},{0,1}},{"a:xy",{1,2,N,N},{0,1}},{"a:?d",{1,N,0,2},{0,1}},{"/a/b:c?d",{4,5,1,6},{3,4}},{"?",{0,N,0,0},{0,0}}}){
  StarAssetPathSplit m={17,18,19,20};StarAssetPathRange r={21,22};auto p=reinterpret_cast<uint8_t const*>(c.s);size_t len=std::strlen(c.s);auto before=star_asset_path_call_count(0);check(star_asset_path_split(p,len,&m)==0,"ABI success");check(m.base_len==c.want.base_len&&m.sub_start==c.want.sub_start&&m.sub_count==c.want.sub_count&&m.directive_start==c.want.directive_start,"literal raw metadata BEFORE clamping");check(star_asset_path_call_count(0)==before+1,"split scoped receipt");before=star_asset_path_call_count(1);check(star_asset_path_filename_range(p,len,&r)==0&&r.start==c.range.start&&r.end==c.range.end,"literal absolute range");check(star_asset_path_call_count(1)==before+1,"range scoped receipt");}
 StarAssetPathSplit m={17,18,19,20};auto before=star_asset_path_call_count(0);check(star_asset_path_split(nullptr,1,&m)==2&&m.base_len==17&&m.sub_start==18&&m.sub_count==19&&m.directive_start==20,"invalid untouched");check(star_asset_path_split(nullptr,0,nullptr)==2,"null metadata");check(star_asset_path_split(reinterpret_cast<uint8_t const*>(uintptr_t(-2)),4,&m)==2,"input span overflow");check(star_asset_path_split(nullptr,size_t(PTRDIFF_MAX)+1,&m)==2,"input PTRDIFF overflow");alignas(StarAssetPathSplit) unsigned char b[128]={};check(star_asset_path_split(b,128,reinterpret_cast<StarAssetPathSplit*>(b+32))==2,"overlap beyond parsed prefix");check(star_asset_path_split(b,1,reinterpret_cast<StarAssetPathSplit*>(b+1))==2,"unaligned metadata");check(star_asset_path_split(b,1,reinterpret_cast<StarAssetPathSplit*>(uintptr_t(-8)))==2,"output overflow");check(star_asset_path_call_count(0)==before,"invalid no receipt");StarAssetPathRange r={21,22};before=star_asset_path_call_count(1);check(star_asset_path_filename_range(nullptr,1,&r)==2&&r.start==21&&r.end==22,"range invalid untouched");check(star_asset_path_filename_range(b,128,reinterpret_cast<StarAssetPathRange*>(b+64))==2,"range overlap");check(star_asset_path_filename_range(b,1,reinterpret_cast<StarAssetPathRange*>(b+1))==2,"range alignment");check(star_asset_path_filename_range(reinterpret_cast<uint8_t const*>(uintptr_t(-2)),4,&r)==2,"range input overflow");check(star_asset_path_filename_range(nullptr,size_t(PTRDIFF_MAX)+1,&r)==2,"range PTRDIFF");check(star_asset_path_filename_range(b,1,reinterpret_cast<StarAssetPathRange*>(uintptr_t(-8)))==2,"range output overflow");check(star_asset_path_call_count(1)==before&&star_asset_path_call_count(100)==0,"range invalid no receipt");check(star_asset_path_split(nullptr,0,&m)==0&&m.base_len==N,"nullable empty");check(star_asset_path_filename_range(nullptr,0,&r)==0&&r.start==0&&r.end==0,"range nullable empty");uint64_t child=99;std::thread t([&]{child=star_asset_path_call_count(0)+star_asset_path_call_count(1);});t.join();check(child==0,"thread local receipt");}
#endif
int main(int argc,char**){if(auto p=getenv("LAB_OBSERVATIONS"))stream.open(p,std::ios::binary);check(bool(stream),"ordered stream");std::string payload("prefix\0suffix",13);StarException error(payload,false);check(errorBytes(error).find(payload)!=std::string::npos,"literal full exception bytes include NUL");check(AssetPath::filename("/a/b:c?d")=="b:c?","literal legacy filename count");check(AssetPath::extension("/a/f.ext:q?d")=="ext:q?","literal legacy extension count");check(AssetPath::setSubPath("a","")=="a:","explicit empty optional present");std::vector<std::string> atoms={"","a","/",":","?","??","x:y","flipx",".","é","😀",std::string("\0",1),std::string("\xff",1),std::string("\xc0\x80",2)};for(auto const&a:atoms)for(auto const&b:atoms)for(auto const&c:atoms)test(a+b+c);for(int n:{998,999,1000,1001,1024}){test("/a:x?"+std::string(n,'z')+"??flipx");test("/a:x?"+std::string(n-1,'z'));}test("/opensb_data;abc?flipx");std::mt19937 rng(0x41535354);std::string alphabet="ab/:?.012";for(int n=0;n<5000;++n){std::string s;for(unsigned i=0,len=rng()%60;i<len;++i)s+=alphabet[rng()%alphabet.size()];test(s);}uint64_t receipts=0;
#ifdef STAR_USE_RUST_ASSET_PATH
 abi();receipts=star_asset_path_call_count(0)+star_asset_path_call_count(1);check(receipts>0&&argc==1,"receipt missing");
#endif
 std::cout<<"{\"cases\":"<<cases<<",\"checks\":"<<checks<<",\"receipts\":"<<receipts<<"}\n";}
